BEGIN;
CREATE TABLE payroll_setting_revisions(workspace_id text NOT NULL REFERENCES workspaces(id), revision integer NOT NULL CHECK(revision>0), effective_from date NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(workspace_id,revision));
CREATE TABLE payroll_exception_revisions(workspace_id text NOT NULL REFERENCES workspaces(id),employee_id text NOT NULL REFERENCES employees(id),revision integer NOT NULL CHECK(revision>0),effective_from date NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,employee_id,revision));
CREATE TABLE payroll_grant_revisions(workspace_id text NOT NULL REFERENCES workspaces(id),employee_id text NOT NULL REFERENCES employees(id),revision integer NOT NULL CHECK(revision>0),payload jsonb NOT NULL,PRIMARY KEY(workspace_id,employee_id,revision));
CREATE VIEW payroll_grants_current AS SELECT DISTINCT ON(workspace_id,employee_id) workspace_id,employee_id,revision,payload FROM payroll_grant_revisions ORDER BY workspace_id,employee_id,revision DESC;
CREATE TABLE payroll_runs(workspace_id text NOT NULL REFERENCES workspaces(id),id uuid NOT NULL,start_date date NOT NULL,end_date date NOT NULL,correction_of uuid,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,correction_of) REFERENCES payroll_runs(workspace_id,id));
CREATE UNIQUE INDEX payroll_one_original_period ON payroll_runs(workspace_id,start_date,end_date) WHERE correction_of IS NULL;
CREATE UNIQUE INDEX payroll_one_correction ON payroll_runs(workspace_id,correction_of) WHERE correction_of IS NOT NULL;
CREATE TABLE payroll_run_revisions(workspace_id text NOT NULL,run_id uuid NOT NULL,revision integer NOT NULL CHECK(revision>0),payload jsonb NOT NULL,snapshot jsonb,PRIMARY KEY(workspace_id,run_id,revision),FOREIGN KEY(workspace_id,run_id) REFERENCES payroll_runs(workspace_id,id));
CREATE VIEW payroll_runs_current AS SELECT DISTINCT ON(workspace_id,run_id) workspace_id,run_id,revision,payload,snapshot FROM payroll_run_revisions ORDER BY workspace_id,run_id,revision DESC;
CREATE TABLE payroll_command_receipts(workspace_id text NOT NULL REFERENCES workspaces(id),actor_id text NOT NULL REFERENCES employees(id),operation_id uuid NOT NULL,command_hash text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,actor_id,operation_id));
CREATE TABLE payroll_documents(workspace_id text NOT NULL, id uuid NOT NULL,run_id uuid NOT NULL,employee_id text REFERENCES employees(id),kind text NOT NULL CHECK(kind IN('EMPLOYEE_STATEMENT','COMPANY_SUMMARY','PAYMENT_INSTRUCTIONS')),filename text NOT NULL,sha256 text NOT NULL,content bytea NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,run_id) REFERENCES payroll_runs(workspace_id,id));
CREATE UNIQUE INDEX payroll_unique_document ON payroll_documents(workspace_id,run_id,kind,COALESCE(employee_id,''));
CREATE TABLE payroll_publications(workspace_id text NOT NULL,run_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,run_id),FOREIGN KEY(workspace_id,run_id) REFERENCES payroll_runs(workspace_id,id));
CREATE TABLE payroll_jobs(id uuid PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),run_id uuid,kind text NOT NULL CHECK(kind IN('PREPARE','PDF','PUBLISH','REMINDER')),business_key text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','RUNNING','SUCCEEDED','FAILED')),payload jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),lease_token uuid,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT clock_timestamp(),error text,UNIQUE(workspace_id,business_key),FOREIGN KEY(workspace_id,run_id) REFERENCES payroll_runs(workspace_id,id));
CREATE TABLE payroll_notice_receipts(workspace_id text NOT NULL REFERENCES workspaces(id),business_key text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(workspace_id,business_key));
CREATE FUNCTION payroll_protect_approval() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM payroll_run_revisions WHERE workspace_id=NEW.workspace_id AND run_id=NEW.run_id AND payload->>'status'='APPROVED') THEN RAISE EXCEPTION 'approved_payroll_immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER payroll_approved_frozen BEFORE INSERT ON payroll_run_revisions FOR EACH ROW EXECUTE FUNCTION payroll_protect_approval();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['payroll_setting_revisions','payroll_exception_revisions','payroll_grant_revisions','payroll_runs','payroll_run_revisions','payroll_command_receipts','payroll_documents','payroll_publications','payroll_notice_receipts'] LOOP EXECUTE format('CREATE TRIGGER payroll_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION nevora_immutable_ledger()',t); EXECUTE format('CREATE TRIGGER payroll_no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION nevora_immutable_ledger()',t); END LOOP; END $$;
COMMIT;
